/**
 * SM-2 spaced-repetition scheduler (SuperMemo 2, P. Wozniak 1987) with three
 * pragmatic adjustments that keep the schedule reliable for exam study:
 *
 * 1. Relearning step: a failed item is due again after RELEARN_MINUTES instead
 *    of one day, so it is re-tested within the same session.
 * 2. Early reviews: answering an item correctly before it is due (extra
 *    practice) does not grow the interval. SM-2 assumes the item was reviewed
 *    at the scheduled time, so counting early successes would inflate intervals.
 *    Early failures still count as lapses.
 * 3. Intervals are capped at MAX_INTERVAL_DAYS and always grow by at least one
 *    day on a successful review.
 * 5. Adaptive options (Phase 2): a per-user interval modifier calibrated from
 *    observed retention, credit for successful late reviews (half of the
 *    overdue time counts toward the interval, as the word survived longer than
 *    planned), and a small deterministic fuzz that spreads reviews over nearby
 *    days so they do not pile up on one day.
 * 4. The ease factor only changes on reviews of a learned item (repetitions > 0).
 *    Missing a word the first time it is studied, or during relearning, says
 *    nothing about how well it is retained between spaced reviews, so it must
 *    not permanently shorten that word's future intervals.
 *
 * All functions are pure: time is passed in explicitly.
 */
import type { LearningStatus, SrsState, WordProgress } from '../types.ts';

export const INITIAL_EASE = 2.5;
export const MIN_EASE = 1.3;
export const MAX_EASE = 3.0;
export const RELEARN_MINUTES = 10;
export const MAX_INTERVAL_DAYS = 365;
export const MASTERED_INTERVAL_DAYS = 21;
/** A review counts as early if made this long before it was due. */
export const EARLY_TOLERANCE_MS = 60 * 60 * 1000;

const DAY_MS = 24 * 60 * 60 * 1000;

export type Quality = 0 | 1 | 2 | 3 | 4 | 5;

export type SrsFields = SrsState;

export interface ScheduleResult extends SrsFields {
  /** True when this review was early practice and did not change the schedule. */
  wasEarly: boolean;
}

export function isPassing(quality: number): boolean {
  return quality >= 3;
}

/** SM-2 ease-factor update: EF' = EF + (0.1 - (5 - q) * (0.08 + (5 - q) * 0.02)). */
export function nextEase(ease: number, quality: number): number {
  const q = clampQuality(quality);
  const updated = ease + (0.1 - (5 - q) * (0.08 + (5 - q) * 0.02));
  return round2(Math.min(MAX_EASE, Math.max(MIN_EASE, updated)));
}

export function statusFor(repetitions: number, intervalDays: number, hadLapseBefore: boolean): LearningStatus {
  if (repetitions === 0) return hadLapseBefore ? 'relearning' : 'learning';
  if (intervalDays >= MASTERED_INTERVAL_DAYS) return 'mastered';
  return 'review';
}

export function initialSrs(): SrsFields {
  return {
    repetitions: 0,
    lapses: 0,
    easeFactor: INITIAL_EASE,
    intervalDays: 0,
    status: 'new',
    lastReviewedAt: null,
    nextReviewAt: null,
  };
}

export function isDue(fields: Pick<SrsFields, 'nextReviewAt' | 'status'>, now: Date): boolean {
  if (fields.status === 'new' || fields.nextReviewAt === null) return false;
  return Date.parse(fields.nextReviewAt) <= now.getTime();
}

export const MIN_INTERVAL_MODIFIER = 0.6;
export const MAX_INTERVAL_MODIFIER = 1.4;
export const FUZZ_RATIO = 0.05;

export interface ScheduleOptions {
  /** Multiplies intervals from the second successful review on. Clamped to [0.6, 1.4]. */
  intervalModifier?: number;
  /** Stable key (e.g. word id + competency) for deterministic fuzz. No fuzz when omitted. */
  fuzzKey?: string;
}

/** Deterministic hash of a string to [0, 1). */
export function hash01(key: string): number {
  let h = 2166136261;
  for (let i = 0; i < key.length; i++) {
    h ^= key.charCodeAt(i);
    h = Math.imul(h, 16777619);
  }
  return ((h >>> 0) % 100000) / 100000;
}

/**
 * Compute the next schedule for an item after a review with the given quality.
 */
export function schedule(prev: SrsFields, quality: number, now: Date, options: ScheduleOptions = {}): ScheduleResult {
  const modifier = Math.min(MAX_INTERVAL_MODIFIER, Math.max(MIN_INTERVAL_MODIFIER, options.intervalModifier ?? 1));
  const q = clampQuality(quality);
  const nowIso = now.toISOString();

  const dueMs = prev.nextReviewAt ? Date.parse(prev.nextReviewAt) : null;
  const early =
    prev.repetitions > 0 && dueMs !== null && now.getTime() < dueMs - EARLY_TOLERANCE_MS;

  if (isPassing(q)) {
    if (early) {
      // Extra practice: keep the existing schedule untouched.
      return { ...prev, lastReviewedAt: nowIso, wasEarly: true };
    }
    const repetitions = prev.repetitions + 1;
    const easeFactor = prev.repetitions > 0 ? nextEase(prev.easeFactor, q) : prev.easeFactor;
    let intervalDays: number;
    let minimum: number;
    if (repetitions === 1) {
      intervalDays = 1;
      minimum = 1;
    } else if (repetitions === 2) {
      intervalDays = Math.round(6 * modifier);
      minimum = 2;
    } else {
      let base = Math.max(prev.intervalDays, 1);
      const elapsed = prev.lastReviewedAt ? (now.getTime() - Date.parse(prev.lastReviewedAt)) / DAY_MS : base;
      if (elapsed > base) base += (elapsed - base) / 2; // remembered despite the delay
      intervalDays = Math.round(base * easeFactor * modifier);
      minimum = Math.floor(Math.max(prev.intervalDays, 1)) + 1;
    }
    if (options.fuzzKey && intervalDays >= 3) {
      const f = (hash01(`${options.fuzzKey}:${repetitions}`) * 2 - 1) * FUZZ_RATIO;
      intervalDays = Math.round(intervalDays * (1 + f));
    }
    intervalDays = Math.min(Math.max(intervalDays, minimum), MAX_INTERVAL_DAYS);
    return {
      ...(repetitions >= 2 ? { modifier } : {}),
      repetitions,
      lapses: prev.lapses,
      easeFactor,
      intervalDays,
      status: statusFor(repetitions, intervalDays, prev.lapses > 0),
      lastReviewedAt: nowIso,
      nextReviewAt: new Date(now.getTime() + intervalDays * DAY_MS).toISOString(),
      wasEarly: false,
    };
  }

  // Failed recall: reset repetitions, lower ease, relearn soon.
  // A lapse is counted only when the item had been successfully learned before.
  const lapses = prev.repetitions > 0 ? prev.lapses + 1 : prev.lapses;
  const intervalDays = RELEARN_MINUTES / (24 * 60);
  return {
    repetitions: 0,
    lapses,
    easeFactor: prev.repetitions > 0 ? nextEase(prev.easeFactor, q) : prev.easeFactor,
    intervalDays,
    status: statusFor(0, intervalDays, lapses > 0),
    lastReviewedAt: nowIso,
    nextReviewAt: new Date(now.getTime() + RELEARN_MINUTES * 60 * 1000).toISOString(),
    wasEarly: early,
  };
}

export function srsFieldsOf(p: WordProgress): SrsFields {
  return {
    repetitions: p.repetitions,
    lapses: p.lapses,
    easeFactor: p.easeFactor,
    intervalDays: p.intervalDays,
    status: p.status,
    lastReviewedAt: p.lastReviewedAt,
    nextReviewAt: p.nextReviewAt,
  };
}

function clampQuality(q: number): Quality {
  if (!Number.isFinite(q)) return 0;
  return Math.min(5, Math.max(0, Math.round(q))) as Quality;
}

function round2(n: number): number {
  return Math.round(n * 100) / 100;
}
